// internalDelayDCGateRow is a frozen internal-delay descriptor of the PT5WKA
// census (arm64 generators of census/pt5wka, key fam:variant/seed in name;
// lft has C2 = 0, lftc a random C2, sc+6 lftc with its delay channel
// scaled by 1e6) with the 320-bit DC g0 of its closed DC pencil, the bar0
// (per-channel bar; the core's for C2 = 0) and terms T0 of its U-1 bar, and
// (the pairs lftc/sc+6, n2/n2s and sc−6, delay channels rescaled exactly)
// the C2D class of each cell (U unverified, N nil; ? where the arm64 and
// amd64 census rows, 1 ulp apart, disagree, or these arm64 entries give
// another class on amd64: lft/256 at dt 0.01, 1.1 to 1.2 bars on arm64;
// strad1m-lft/212's unverified cells, 2 to 5 bars on arm64, which move 2×
// between arm64 and amd64 (a nil there is still checked against the bar);
// A nil on arm64, either elsewhere: sc−6/220 at 0.90 bars on arm64, its
// arm64 entries unverified on amd64).
type internalDelayDCGateRow struct {
	name                  string
	A, E, B, C, D         *mat.Dense
	tau                   []float64
	B2, C2, D12, D21, D22 *mat.Dense
	g0, bar0, t0          float64
	classes               map[string]byte
}

